input.command:
cd /tmp/probe-html && mkdir -p p1/src/dir/sub && cd p1/src && \
cat > a.h <<'EOF'
/** \file a.h
 *  Lowercase a header.
 */
/** A documented class in a.h */
class Foo {
public:
  /** ctor */
  Foo();
  /** a method
   *  @param x an int
   *  @return nothing
   */
  void bar(int x);
  int m_field; ///< a field
};
EOF
cat > A.h <<'EOF'
/** \file A.h
 * Uppercase A header. */
class Bar { public: int q; };
EOF
cat > my_file.h <<'EOF'
/** \file my_file.h
 * underscore header */
struct MyStruct { int a; };
EOF
cat > My_File.h <<'EOF'
/** \file My_File.h
 * Mixed case underscore */
union MyUnion { int a; float b; };
EOF
cat > foo-bar.h <<'EOF'
/** \file foo-bar.h
 * dash header */
void dashfunc(void);
EOF
cat > 'a+b.h' <<'EOF'
/** \file a+b.h
 * plus header */
void plusfunc(void);
EOF
cat > dir/sub/x.h <<'EOF'
/** \file x.h
 * nested header */
class Nested { public: void f(); };
EOF
cat > ns.h <<'EOF'
/** \file ns.h */
/** namespace X */
namespace X {
  /** nested namespace */
  namespace Inner {
     /** class in X::Inner */
     class Deep { public: void g(); };
  }
  /** a template class */
  template<class T, int N> class TmplClass { public: T data[N]; };
  /** func in X */
  void xfunc(int);
  /** a var */
  extern int xvar;
}
/** \defgroup mygroup My Group Name
 *  Group docs here.
 *  @{
 */
/** grouped func */
void gfunc(void);
/** @} */
/** \defgroup other_group Other_Group
 * more docs */
EOF
cat > globals.c <<'EOF'
/** \file globals.c
 * globals */
#include "a.h"
/** a global function
 * @param n count
 */
int global_func(int n) { return n; }
/** a global var */
int g_var = 0;
/** a macro */
#define MY_MACRO 1
/** a typedef */
typedef int my_int_t;
/** an enum */
enum MyEnum { E_ONE, /**< one */ E_TWO /**< two */ };
EOF
mkdir -p /tmp/probe-html/p1 && cat > /tmp/probe-html/p1/page.md <<'EOF'
